<template><f7-page class="cy-mobile-surface" @page:afterin="load"><f7-navbar title="导入导出" back-link="返回"/><main class="cy-data-body"><p v-if="error" class="cy-message">{{error}}</p><p v-if="busy" role="status">{{progress||'正在处理…'}}</p><f7-list strong inset><f7-list-item title="导入账单文件 / 截图" link="/user/import"/><f7-list-item title="下载导入模板" link="#" @click="template"/></f7-list><f7-block-title>导出数据</f7-block-title><p class="cy-muted">CSV / Excel 用于查看和交换账单，退款支出按净额展示。完整还原退款关联、附件、优惠、手续费关联及所有设置，请使用数据备份。</p><div class="cy-panel"><div class="cy-data-presets"><button v-for="p in datePresets" :key="p.id" type="button" :aria-pressed="activePreset===p.id" @click="applyPreset(p.id)">{{p.label}}</button></div><div class="cy-data-dates"><label>开始日期<input type="date" v-model="start"/></label><label>结束日期<input type="date" v-model="end"/></label></div><ledger-scope-fields accounts-enabled categories-enabled tags-enabled v-model:book-ids="bookIds" v-model:account-ids="accountIds" v-model:category-ids="categoryIds" v-model:tag-ids="tagIds"/><label class="cy-data-type">账单类型<select v-model="type"><option value="all">全部</option><option value="expense">支出</option><option value="income">收入</option><option value="transfer">转账</option><option value="debt">债务往来</option></select></label><p class="cy-data-count">所选范围 {{filtered.length}} 笔<small v-if="!filtered.length" class="cy-muted">（暂无可导出账单）</small></p><button class="cy-button" :disabled="busy||!filtered.length" @click="exportCsv">导出 CSV</button><button class="cy-button" :disabled="busy||!filtered.length" @click="exportXlsx">导出 Excel</button><button class="cy-button" :disabled="busy||!filtered.length" @click="pictures">导出账单图片</button></div><f7-list strong inset><f7-list-item title="导出资产账户 Excel" link="#" @click="assets"/><f7-list-item title="导出投资与加密资产流水" link="#" @click="investment"/></f7-list><f7-block-title>导入记录</f7-block-title><div v-for="batch in batches" :key="batch.id" class="cy-panel cy-import-batch"><div><strong>{{batch.name||'账单导入'}}</strong><p>{{moment.unix(batch.createdAt).tz(scope.timeZone).format('YYYY-MM-DD HH:mm')}} · {{batch.count}} 笔</p></div><button class="cy-button" :class="{'cy-danger':!batch.deleted}" :disabled="busy||batch.deleted" @click="undo(batch)">{{batch.deleted?'已撤回':'撤回'}}</button></div><p v-if="!batches.length" class="cy-muted">暂无导入记录</p></main></f7-page></template>
<script setup lang="ts">
import {ref,computed} from 'vue';import axios from 'axios';import moment from 'moment-timezone';
import LedgerScopeFields from '@/components/mobile/LedgerScopeFields.vue';import {useMobileLedger,LedgerDecimal} from '@/lib/mobile-ledger.ts';import {useLedgerScopeStore} from '@/stores/ledgerScope.ts';import {useAccountsStore} from '@/stores/account.ts';import {ledgerEntryRows,exportLedgerEntries,exportLedgerWorkbook,exportLedgerPictures,downloadLedgerFile} from '@/lib/ledger-export.ts';import {investments,investmentError} from '@/lib/investments.ts';import {useI18nUIComponents} from '@/lib/ui/mobile.ts';
const ledger=useMobileLedger({bookIds:()=>[],applyFilters:()=>false}),scope=useLedgerScopeStore(),accounts=useAccountsStore(),{showConfirm,showToast}=useI18nUIComponents(),start=ref(''),end=ref(''),bookIds=ref<string[]>([]),accountIds=ref<string[]>([]),categoryIds=ref<string[]>([]),tagIds=ref<string[]>([]),type=ref('all'),error=ref(''),busy=ref(false),progress=ref('');
interface Batch{id:string;name:string;count:string;createdAt:number;deleted:boolean}const batches=ref<Batch[]>([]);
const datePresets=[{id:'all',label:'全部'},{id:'month',label:'本月'},{id:'lastMonth',label:'上月'},{id:'year',label:'今年'}] as const;
const activePreset=computed(()=>{
 const now=moment().tz(scope.timeZone);
 if(!start.value&&!end.value)return 'all';
 if(start.value===now.clone().startOf('month').format('YYYY-MM-DD')&&end.value===now.clone().endOf('month').format('YYYY-MM-DD'))return 'month';
 const prev=now.clone().subtract(1,'month');
 if(start.value===prev.clone().startOf('month').format('YYYY-MM-DD')&&end.value===prev.clone().endOf('month').format('YYYY-MM-DD'))return 'lastMonth';
 if(start.value===now.clone().startOf('year').format('YYYY-MM-DD')&&end.value===now.clone().endOf('year').format('YYYY-MM-DD'))return 'year';
 return '';
});
function applyPreset(id:'all'|'month'|'lastMonth'|'year'){
 const now=moment().tz(scope.timeZone);
 if(id==='all'){start.value='';end.value='';}
 else if(id==='month'){start.value=now.clone().startOf('month').format('YYYY-MM-DD');end.value=now.clone().endOf('month').format('YYYY-MM-DD');}
 else if(id==='lastMonth'){const p=now.clone().subtract(1,'month');start.value=p.clone().startOf('month').format('YYYY-MM-DD');end.value=p.clone().endOf('month').format('YYYY-MM-DD');}
 else{start.value=now.clone().startOf('year').format('YYYY-MM-DD');end.value=now.clone().endOf('year').format('YYYY-MM-DD');}
}
const filtered=computed(()=>ledger.entries.value.filter(e=>(!start.value||e.day>=start.value)&&(!end.value||e.day<=end.value)&&(!bookIds.value.length||bookIds.value.includes(e.bookId))&&(!accountIds.value.length||accountIds.value.includes(e.accountId)||accountIds.value.includes(e.destinationAccountId))&&(!categoryIds.value.length||categoryIds.value.includes(e.categoryId)||categoryIds.value.includes(e.primaryCategoryId))&&(!tagIds.value.length||tagIds.value.some(t=>e.tagIds.includes(t)))&&(type.value==='all'||e.type===({expense:3,income:2,transfer:4} as Record<string,number>)[type.value]||type.value==='debt'&&[e.accountId,e.destinationAccountId].some(id=>[5,6].includes(accounts.allAccountsMap[id]?.category||0)))));
async function load(){await ledger.load(0,moment().add(100,'year').unix());try{batches.value=(await axios.get('v1/ledger/imports')).data.result;}catch(e){error.value=investmentError(e);}}
function exportCsv(){if(!filtered.value.length)return;exportLedgerEntries(filtered.value,scope.timeZone);showToast('已导出 CSV 文件');}
function exportXlsx(){if(!filtered.value.length)return;exportLedgerWorkbook(ledgerEntryRows(filtered.value,scope.timeZone));showToast('已导出 Excel 文件');}
async function run(action:()=>Promise<void>){busy.value=true;error.value='';try{await action();}catch(e){error.value=investmentError(e);}finally{busy.value=false;progress.value='';}}
function pictures(){if(!filtered.value.length)return;return run(async()=>{await exportLedgerPictures(filtered.value,scope.timeZone,value=>progress.value=value);showToast('账单图片导出完成');});}
function investment(){return run(async()=>{downloadLedgerFile(await investments.export(),`OpenBill-投资-${moment().format('YYYYMMDD-HHmmss')}.csv`,'text/csv;charset=utf-8');showToast('已导出投资流水');});}
const accountKindLabels:Record<string,string>={cash:'现金',checking:'储蓄卡',credit:'信用卡',virtual:'电子钱包',debt:'借入/欠款',receivables:'借出/应收',investment:'投资账户',savings:'定期存款',reimbursement:'报销账户',crypto_exchange:'加密交易所',crypto_wallet:'加密钱包'};
const categoryKindLabels:Record<number,string>={1:'现金',2:'储蓄卡',3:'信用卡',4:'电子钱包',5:'借入/欠款',6:'借出/应收',7:'投资账户',8:'储蓄账户',9:'其他'};
function assets(){exportLedgerWorkbook([['账户','币种','余额','类型','计入总资产'],...accounts.allPlainAccounts.filter(a=>!a.subAccounts?.length).map(a=>[a.name,a.currency,new LedgerDecimal(a.balance).div(100).toFixed(2),accountKindLabels[a.assetProfile.kind||'']||categoryKindLabels[a.category]||'资金账户',a.assetProfile.excludeFromTotal?'否':'是'])],'资产账户');showToast('已导出资产账户 Excel');}
function template(){exportLedgerWorkbook([['日期','类型','分类','子分类','账户','币种','金额','账户2','账户2币种','账户2金额','标签','备注'],['2026-01-01 12:00:00','支出','餐饮','早餐','现金','CNY','12.50','','','','','示例，请替换为自己的数据']],'导入模板');showToast('已下载导入模板');}
function undo(batch:Batch){showConfirm(`确定撤回「${batch.name||'账单导入'}」（共 ${batch.count} 笔）尚存在的全部账单，并恢复对应账户余额？后续修改过的导入账单也会一并撤回。`,()=>{void run(async()=>{await axios.post('v1/ledger/imports/undo',{id:batch.id});await accounts.loadAllAccounts({force:true});await load();showToast('已撤回该次导入');});},undefined,{title:'撤回导入批次',confirmText:'确认撤回',destructive:true});}
</script><style scoped>.cy-data-body{padding:12px 14px 80px}.cy-data-presets{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:12px}.cy-data-presets button{border:1px solid var(--cy-line);border-radius:16px;background:var(--cy-bg);color:var(--cy-muted);padding:5px 12px;font-size:12px}.cy-data-presets button[aria-pressed=true]{background:var(--cy-soft);border-color:var(--cy-accent);color:var(--cy-accent);font-weight:600}.cy-data-dates{display:grid;grid-template-columns:1fr 1fr;gap:12px}.cy-data-dates input,.cy-data-type select{display:block;width:100%;padding:9px 0;color:var(--cy-ink);background:transparent}.cy-data-type{display:block;margin-top:12px}.cy-data-count{margin:10px 0 6px;font-size:13px}.cy-data-body .cy-button{margin:6px 8px 6px 0}.cy-import-batch{display:flex;gap:12px;justify-content:space-between;align-items:center;overflow-wrap:anywhere}.cy-import-batch p{font-size:12px;color:var(--cy-muted)}</style>
